91	enum RecordingGPSQuality: Equatable {
92	    case waiting
93	    case stabilizing
94	    case good
95	    case weak
96	    case unavailable
97	
98	    var title: String {
99	        switch self {
100	        case .waiting: return "等待 GPS"
101	        case .stabilizing: return "校准中"
102	        case .good: return "GPS 稳定"
103	        case .weak: return "GPS 弱"
104	        case .unavailable: return "定位不可用"
105	        }
106	    }
107	
108	    var systemImage: String {
109	        switch self {
110	        case .waiting: return "location"
111	        case .stabilizing: return "scope"
112	        case .good: return "location.fill"
113	        case .weak: return "location.slash"
114	        case .unavailable: return "exclamationmark.triangle.fill"
115	        }
116	    }
117	
118	    var tint: Color {
119	        switch self {
120	        case .waiting, .stabilizing: return Color.teslaSecondaryText
121	        case .good: return Color.teslaGreen
122	        case .weak: return .orange
123	        case .unavailable: return .red
124	        }
125	    }
126	}
