294	    func stop() -> NinebotRecordedRide? {
295	        guard isRecording, let startedAt else { return nil }
296	        let endedAt = Date()
297	        isRecording = false
298	        self.endedAt = endedAt
299	
300	        let correctedDistanceMeters = NinebotRecordedRide.recalculatedDistanceMeters(from: points)
301	        let finalDistanceMeters = correctedDistanceMeters > 0 ? correctedDistanceMeters : distanceMeters
302	        let durationHours = max(endedAt.timeIntervalSince(startedAt) / 3600, 0)
303	        let averageSpeed: Double
304	        if durationHours > 0 {
305	            averageSpeed = (finalDistanceMeters / 1000) / durationHours
306	        } else if !speedSamples.isEmpty {
307	            averageSpeed = speedSamples.reduce(0, +) / Double(speedSamples.count)
308	        } else {
309	            averageSpeed = 0
310	        }
311	
312	        return NinebotRecordedRide(
313	            vehicleSN: vehicleSN,
314	            startedAt: startedAt,
315	            endedAt: endedAt,
316	            distanceMeters: finalDistanceMeters,
317	            maxSpeedKmh: maxSpeedKmh,
318	            averageSpeedKmh: averageSpeed,
319	            maxAccelerationG: maxAccelerationG,
320	            points: points
321	        )
322	    }
