368	    private func consumeMotion(_ motion: CMDeviceMotion) {
369	        if let ignoreMotionUntil, Date() < ignoreMotionUntil {
370	            currentAccelerationG = 0
371	            return
372	        }
373	
374	        if let lastMotionTimestamp {
375	            let deltaTime = motion.timestamp - lastMotionTimestamp
376	            if deltaTime <= 0 || deltaTime > maximumMotionSampleGap {
377	                self.lastMotionTimestamp = motion.timestamp
378	                smoothedMotionG = nil
379	                currentAccelerationG = 0
380	                ignoreMotionUntil = Date().addingTimeInterval(motionCooldownDuration)
381	                return
382	            }
383	        }
384	
385	        if let lastMotionTimestamp, motion.timestamp < lastMotionTimestamp {
386	            currentAccelerationG = 0
387	            return
388	        }
389	        lastMotionTimestamp = motion.timestamp
390	
391	        let acceleration = motion.userAcceleration
392	        let g = sqrt(
393	            acceleration.x * acceleration.x +
394	            acceleration.y * acceleration.y +
395	            acceleration.z * acceleration.z
396	        )
397	        guard g.isFinite, g <= maximumReasonableMotionG else {
398	            currentAccelerationG = 0
399	            return
400	        }
401	
402	        let normalizedG = g < 0.025 ? 0 : g
403	        let previousG = smoothedMotionG ?? 0
404	        let filteredG = previousG + (normalizedG - previousG) * 0.18
405	        let maxStep = 0.08
406	        let rateLimitedG = min(max(filteredG, previousG - maxStep), previousG + maxStep)
407	        smoothedMotionG = min(max(rateLimitedG, 0), maximumReasonableMotionG)
408	
409	        currentAccelerationG = smoothedMotionG ?? 0
410	        if isRecording {
411	            maxAccelerationG = max(maxAccelerationG, currentAccelerationG)
412	        }
413	    }
