                savedRecord.associatedRideID = rideID
                model.saveRecordedRide(savedRecord)
                pendingRecord = nil
            }
        }
        .onAppear {
            recorder.startPreview()
        }
        .onDisappear {
            recorder.stopPreviewIfIdle()
        }
    }
